const lvlOf = s => Math.max(1, Math.min(5, parseInt(String(s).replace(/^\D*/, ""), 10) || 1));
const timeOf = s => (/^(std|default|see page)?$/i.test(String(s ?? "").trim()) ? "" : String(s).trim());

/**
 * One book ritual as a ritual the Storyteller's window fills in from: keywords, strength (its level, read as
 * successes), casting time, area when it works on a place or area, and a note with what it does, what resists it and
 * the page. Null when there is no such entry.
 */
export function bookRitual(set, i) {
  const b = BOOK_RITUALS[set], r = b?.list?.[i];
  if ( !r ) return null;
  const resist = r.resist && !/^(none|n\/a)$/i.test(r.resist) ? ` Resisted by ${r.resist}.` : "";
  const does = r.does.charAt(0).toUpperCase() + r.does.slice(1);
  const note = `${does}.${resist} ${b.book} ${r.page}.`.replace(/\.\./g, ".");
  return ritualFrom(r.n, {keywords: r.k, strength: lvlOf(r.lvl), step: 2, area: /^(area|place)/i.test(r.who), note, takes: timeOf(r.takes)});
}

/** How many book rituals there are, by set (for the test). */
export const bookRitualCounts = () => Object.fromEntries(Object.entries(BOOK_RITUALS).map(([k, v]) => [k, v.list.length]));
export const knownKeyword = k => !!KEYWORDS[k];
